CREATE DATABASE HOSPITAL_MANAGEMENT;

CREATE TABLE PATIENTS (PATIENT_ID INT PRIMARY KEY AUTO_INCREMENT,NAME VARCHAR(100),AGE INT,GENDER VARCHAR(10),PHONE VARCHAR(15),CITY VARCHAR(50));

CREATE TABLE DOCTORS(DOCTOR_ID INT PRIMARY KEY AUTO_INCREMENT,NAME VARCHAR(100),SPECIALIZATION VARCHAR(50),CONSULTATION_FEE DECIMAL(10,2));

CREATE TABLE APPOINTMENTS (APPOINTMENT_ID INT PRIMARY KEY AUTO_INCREMENT,PATIENT_ID INT,DOCTOR_ID INT,APPOINTMENT_DATE DATE,STATUS VARCHAR(20),FOREIGN KEY (PATIENT_ID) REFERENCES PATIENTS(PATIENT_ID),FOREIGN KEY (DOCTOR_ID) REFERENCES DOCTORS(DOCTOR_ID));

CREATE TABLE TREATMENTS (TREATMENT_ID INT PRIMARY KEY AUTO_INCREMENT,APPOINTMENT_ID INT,TREATEMENTS_DETAILS VARCHAR(255),COST DECIMAL(10,2),FOREIGN KEY (appointment_id) REFERENCES Appointments(appointment_id));

CREATE TABLE BILLING(BILL_ID INT PRIMARY KEY AUTO_INCREMENT,PATIENT_ID INT,TOTAL_AMOUNT DECIMAL(10,2),PAYMENT_STATUS VARCHAR(20),FOREIGN KEY (patient_id) REFERENCES Patients(patient_id));

