SELECT * FROM PATIENTS WHERE CITY = 'CHENNAI';

SELECT NAME,CONSULTATION_FEE FROM DOCTORS WHERE CONSULTATION_FEE > 500;

SELECT * FROM APPOINTMENTS WHERE STATUS = 'COMPLETED';

SELECT PATIENTS.NAME,DOCTORS.NAME,APPOINTMENTS.APPOINTMENT_DATE FROM PATIENTS JOIN APPOINTMENTS ON PATIENTS.PATIENT_ID = APPOINTMENTS.PATIENT_ID JOIN DOCTORS ON DOCTORS.DOCTOR_ID = APPOINTMENTS.DOCTOR_ID;

SELECT PATIENTS.PATIENT_ID,PATIENTS.NAME,SUM(TREATMENTS.COST) AS TOTAL_TREATMENT_COST FROM PATIENTS JOIN APPOINTMENTS ON PATIENTS.PATIENT_ID = APPOINTMENTS.PATIENT_ID JOIN TREATMENTS ON APPOINTMENTS.APPOINTMENT_ID = TREATMENTS.APPOINTMENT_ID GROUP BY PATIENT_ID,NAME ORDER BY TOTAL_TREATMENT_COST DESC;

SELECT PATIENTS.NAME,BILLING.PAYMENT_STATUS FROM PATIENTS JOIN BILLING ON PATIENTS.PATIENT_ID = BILLING.PATIENT_ID WHERE PAYMENT_STATUS = 'UNPAID';

SELECT CITY,COUNT(PATIENT_ID) NO_OF_PATIENTS FROM PATIENTS GROUP BY CITY ORDER BY NO_OF_PATIENTS DESC;

SELECT DOCTORS.NAME,APPOINTMENTS.DOCTOR_ID,COUNT(APPOINTMENTS.APPOINTMENT_ID) AS TOTAL_APPOINTMENTS FROM DOCTORS JOIN APPOINTMENTS ON DOCTORS.DOCTOR_ID = APPOINTMENTS.DOCTOR_ID GROUP BY NAME HAVING COUNT(APPOINTMENTS.DOCTOR_ID) > 5 ;

SELECT TOTAL_AMOUNT AS HIGHEST_BILLING_AMOUNT FROM BILLING GROUP BY TOTAL_AMOUNT HAVING HIGHEST_BILLING_AMOUNT > 800;

SELECT NAME FROM PATIENTS WHERE PATIENT_ID IN (SELECT PATIENT_ID FROM BILLING WHERE TOTAL_AMOUNT = (SELECT MAX(TOTAL_AMOUNT) FROM BILLING));

SELECT DOCTOR_ID,NAME FROM DOCTORS WHERE DOCTOR_ID IN (SELECT DOCTOR_ID FROM APPOINTMENTS WHERE APPOINTMENT_ID IN (SELECT APPOINTMENT_ID FROM TREATMENTS WHERE COST = (SELECT MAX(COST) FROM TREATMENTS)));